# Let's analyze what changes are needed for each case
inputs = ['ycfddx', 'hz', 'dwbjej', 'abvv', 'bhhh']
outputs = ['yhgdcfddx', 'hhg', 'dwbjgdhgdcvj', 'abvv', 'bhhh']

print("Analyzing transformations:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i+1}. '{inp}' → '{outp}'")
    if inp != outp:
        # Find differences
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) < len(outp):
                print(f"   Added characters at end: '{outp[len(inp):]}'")
            else:
                print(f"   Removed characters at end")
        else:
            print(f"   First difference at position {diff_pos}")
            if len(inp) > len(outp):
                print(f"   Removed character '{inp[diff_pos]}'")
            elif len(inp) < len(outp):
                print(f"   Added characters: '{outp[diff_pos:diff_pos+len(inp)-len(outp)]}'")
            else:
                print(f"   Changed '{inp[diff_pos]}' to '{outp[diff_pos]}'")

# Let's try to think of this more systematically
# What if we look for common patterns in the outputs?

print("\nLooking for patterns:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{outp}'")
    # See if we can find a common base that gets modified
    if len(outp) > len(inp):
        added = outp[len(inp):]
        print(f"  Added: '{added}'")

